<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { Radar, LayoutDashboard, Search, Files, SlidersHorizontal, RefreshCw, ArrowUpRight, Bookmark, ChevronLeft, ChevronRight, Mail, LogOut, Plus, FileText, Check, X, Activity, MapPin, Clock, Building2 } from '@lucide/vue'
import { api } from './api'

const user = ref(null), booting = ref(true), busy = ref(false), error = ref(''), message = ref(''), view = ref('dashboard')
const dashboard = ref({ runs:[], expiring:[] }), results = ref({ data:[], current_page:1, last_page:1, total:0 }), profiles = ref([]), documents = ref([]), detail = ref(null), reading = ref(null)
const login = reactive({email:'',password:''}), setup = ref(false), setupName = ref('')
const filters = reactive({ keyword:'', state:'', agency:'', modality:'', scope:'', min_value:'', max_value:'', deadline:'', open:true, bookmarked:false, discarded:false })
const selectedIds = ref([])
const states = 'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ')
const modalities = [[1,'Leilão eletrônico'],[2,'Diálogo competitivo'],[3,'Concurso'],[4,'Concorrência eletrônica'],[5,'Concorrência presencial'],[6,'Pregão eletrônico'],[7,'Pregão presencial'],[8,'Dispensa de licitação'],[9,'Inexigibilidade'],[10,'Manifestação de interesse'],[11,'Pré-qualificação'],[12,'Credenciamento'],[13,'Leilão presencial']]
const labels = { relevant:'Aderente ao escopo', review:'Revisar escopo', excluded:'Inclui obra', pending:'Pendente', met:'Atendido', unmet:'Não atendido', not_applicable:'Não se aplica', ready:'Texto extraído', needs_ocr:'Requer OCR / revisão', failed:'Falha', running:'Em consulta', completed:'Concluída', certificate:'Certificação', attestation:'Atestado', rrt:'Registro de Responsabilidade Técnica - RRT', cnpj:'CNPJ', tender:'Edital' }
const nav = [{id:'dashboard',label:'Visão geral',icon:LayoutDashboard},{id:'opportunities',label:'Oportunidades',icon:Search},{id:'documents',label:'Documentos da empresa',icon:Files},{id:'profiles',label:'Perfis de busca',icon:SlidersHorizontal}]
const title = computed(() => nav.find(n=>n.id===view.value)?.label || 'Oportunidade')
const profileForm = ref(null), uploadKind = ref('attestation'), expires = ref(''), chosenFile = ref(null)
const reviewForm = ref(null), newReq = reactive({source_document_id:'',source_page:1,description:''})
const money = value => value == null ? 'Valor não informado' : new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value)
const date = value => value ? new Date(value).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}) : 'Não informado'
const datetime = value => value ? new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}) : '—'
async function perform(fn) {
  if (busy.value) return
  busy.value=true; error.value=''; message.value=''
  try { await fn() } catch(e) { error.value=e.message; if(e.status===401) user.value=null } finally { busy.value=false }
}
async function loadDashboard() { dashboard.value=await api('dashboard') }
async function loadResults(page=1) { const p = new URLSearchParams(); for(const [k,v] of Object.entries(filters)) if(v!=='' && v!==false) p.set(k,v===true?'1':v); p.set('page',page); results.value=await api('opportunities?'+p) }
async function go(id) { view.value=id; detail.value=null; reading.value=null; await perform(async()=> { if(id==='dashboard') await loadDashboard(); if(id==='opportunities') await loadResults(); if(id==='documents') documents.value=await api('documents'); if(id==='profiles') profiles.value=await api('profiles') }) }
async function signIn() { await perform(async()=> {
  const data = await api(setup.value?'setup':'login',{method:'POST',body:setup.value?{...login,name:setupName.value}:login});
  user.value=data.user; setup.value=false; login.password=''; await loadDashboard()
}) }
async function signOut() { await perform(async()=> { await api('logout',{method:'POST'}); user.value=null; detail.value=null; selectedIds.value=[]; view.value='dashboard' }) }
async function synchronize() { await perform(async()=> { const data=await api('sync',{method:'POST'}); await loadDashboard(); message.value=data.message+' Atualize o painel para acompanhar.' }) }
async function fetchAttachments() { await perform(async()=> { const data=await api('opportunities/'+detail.value.opportunity.id+'/attachments',{method:'POST'}); message.value=data.message+' Reabra a oportunidade após o processamento.' }) }
async function openDetail(id) { await perform(async()=> { detail.value=await api('opportunities/'+id); documents.value=await api('documents'); view.value='detail' }) }
async function toggleBookmark(item) { await perform(async()=> { const data=await api('opportunities/'+item.id,{method:'PATCH',body:{bookmarked:!item.bookmarked}}); item.bookmarked=data.bookmarked }) }
async function toggleDiscard(item) { await perform(async()=> {
  const discarded = !item.discarded
  await api('opportunities/'+item.id+'/discard',{method:'PATCH',body:{discarded}})
  selectedIds.value=selectedIds.value.filter(id=>id!==item.id)
  await loadResults(results.value.current_page)
  if (!results.value.data.length && results.value.current_page>1) await loadResults(results.value.current_page-1)
  await loadDashboard()
  message.value=discarded?'Oportunidade descartada. Pode ser restaurada antes do vencimento; depois será excluída.':'Oportunidade restaurada. Ela aparecerá se continuar compatível com o acervo e com os filtros.'
}) }
function selectPage() {
  const ids = results.value.data.filter(item=>!item.discarded).map(item=>item.id)
  selectedIds.value=[...new Set([...selectedIds.value,...ids])].slice(0,50)
}
async function exportSelected() { await perform(async()=> {
  const blob=await api('opportunities/export',{method:'POST',body:{ids:selectedIds.value},responseType:'blob'})
  const url=URL.createObjectURL(blob), link=document.createElement('a')
  link.href=url; link.download='licitaradar-oportunidades.pdf'; document.body.appendChild(link); link.click(); link.remove()
  setTimeout(()=>URL.revokeObjectURL(url),60000)
  message.value='PDF gerado com '+selectedIds.value.length+' oportunidades selecionadas.'
}) }
function editProfile(p=null) { profileForm.value=p?{...p,keywords:p.keywords.join(', '),states:p.states?.join(', ')||'',modalities:p.modalities||[]}:{name:'',keywords:'projeto, anteprojeto, arquitetura',states:'',modalities:[],agency:'',min_value:null,max_value:null,min_days:3,email:'',active:true} }
async function saveProfile() { await perform(async()=> { const p=profileForm.value; const body={...p,keywords:p.keywords.split(',').map(s=>s.trim()).filter(Boolean),states:p.states.split(',').map(s=>s.trim().toUpperCase()).filter(Boolean),min_value:p.min_value===''?null:p.min_value,max_value:p.max_value===''?null:p.max_value}; await api('profiles'+(p.id?'/'+p.id:''),{method:p.id?'PUT':'POST',body}); profiles.value=await api('profiles'); profileForm.value=null; message.value='Perfil salvo. Será usado na próxima consulta.' }) }
async function toggleProfile(p) { await perform(async()=> { await api('profiles/'+p.id,{method:'PUT',body:{...p,active:!p.active}}); profiles.value=await api('profiles') }) }
async function upload(tender=false) { await perform(async()=> { if(!chosenFile.value) throw new Error('Selecione um arquivo PDF.'); const body=new FormData(); body.append('file',chosenFile.value); body.append('kind',tender?'tender':uploadKind.value); if(expires.value&&!tender) body.append('expires_at',expires.value); if(tender) body.append('opportunity_id',detail.value.opportunity.id); const d=await api('documents',{method:'POST',body}); chosenFile.value=null; if(tender) detail.value=await api('opportunities/'+detail.value.opportunity.id); else documents.value=await api('documents'); message.value=d.status==='ready'?'PDF recebido e texto extraído.':d.status==='needs_ocr'?'PDF recebido. Há páginas sem texto suficiente; é necessário OCR/revisão.':d.error }) }
async function readDocument(id, tender=false) { await perform(async()=> { reading.value=await api((tender?'tender-documents/':'documents/')+id) }) }
function review(req) { reviewForm.value={...req,evidence_document_id:req.evidence_document_id||'',evidence_page:req.evidence_page||1,notes:req.notes||''} }
async function saveReview() { await perform(async()=> { const r=reviewForm.value; await api('requirements/'+r.id,{method:'PATCH',body:{status:r.status,evidence_document_id:r.evidence_document_id||null,evidence_page:r.evidence_page,notes:r.notes}}); detail.value=await api('opportunities/'+detail.value.opportunity.id); reviewForm.value=null }) }
async function addRequirement() { await perform(async()=> { await api('opportunities/'+detail.value.opportunity.id+'/requirements',{method:'POST',body:newReq}); newReq.description=''; detail.value=await api('opportunities/'+detail.value.opportunity.id) }) }
onMounted(async()=> { try { const s=await api('csrf'); setup.value=s.setup; try { user.value=await api('me'); await loadDashboard() } catch(e) { if(e.status!==401) error.value=e.message } } catch(e) { error.value=e.message } finally { booting.value=false } })
</script>

<template>
  <div v-if="booting" class="boot"><Radar :size="38"/><p>Carregando LicitaRadar…</p></div>
  <div v-else-if="!user" class="login-page">
    <section class="login-story"><div class="brand"><Radar :size="32"/><span>Licita<strong>Radar</strong></span></div><span class="eyebrow">ENGENHARIA & ARQUITETURA</span><h1>O próximo projeto<br>começa aqui.</h1><p>Encontre oportunidades públicas, organize seus atestados e avalie cada exigência com clareza.</p><div class="radar-art"><i></i><i></i><i></i><span></span><Radar :size="72"/></div><small>Projetos e anteprojetos · Todo o Brasil · PNCP</small></section>
    <section class="login-panel"><form @submit.prevent="signIn" class="login-box"><span class="eyebrow">SEU RADAR DE OPORTUNIDADES</span><h2>{{ setup?'Configure seu acesso':'Bem-vindo ao LicitaRadar' }}</h2><p>{{ setup?'Crie o primeiro usuário para começar.':'Entre para acompanhar as oportunidades da empresa.' }}</p><label v-if="setup">Nome<input v-model="setupName" required maxlength="120" autocomplete="name"></label><label>E-mail<input v-model="login.email" type="email" required autocomplete="username"></label><label>Senha<input v-model="login.password" type="password" required :minlength="setup?12:1" :autocomplete="setup?'new-password':'current-password'"><small v-if="setup">Mínimo de 12 caracteres.</small></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'Aguarde…':setup?'Criar acesso':'Entrar no painel'}}<ArrowUpRight :size="18"/></button><small>Documentos privados. Acesso restrito à sua equipe.</small></form></section>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar"><a class="brand" href="#" @click.prevent="go('dashboard')"><span class="brand-icon"><Radar :size="26"/></span><span>Licita<strong>Radar</strong><small>INTELIGÊNCIA EM PROJETOS</small></span></a><div class="workspace"><span class="workspace-icon"><Building2 :size="18"/></span><div><strong>Minha empresa</strong><small>Engenharia e arquitetura</small></div><span class="dot"></span></div><span class="nav-caption">ESPAÇO DE TRABALHO</span><nav><button v-for="item in nav" :key="item.id" :class="{active:view===item.id || (item.id==='opportunities'&&view==='detail')}" @click="go(item.id)"><component :is="item.icon" :size="19"/>{{item.label}}<span v-if="item.id==='opportunities'&&dashboard.open" class="nav-count">{{dashboard.open}}</span></button></nav><div class="sidebar-note"><Radar :size="24"/><strong>Foco em quem projeta.</strong><p>Projetos e anteprojetos em todo o país. Objetos com obras são sinalizados.</p><span>FONTE OFICIAL · PNCP</span></div><div class="account"><span class="avatar">{{user.name?.charAt(0)}}</span><div><strong>{{user.name}}</strong><small>{{user.email}}</small></div><button @click="signOut" aria-label="Sair"><LogOut :size="18"/></button></div></aside>
    <div class="main-shell"><header class="topbar"><span>Espaço de trabalho <span class="separator">/</span> <strong>{{title}}</strong></span><div><span class="source-pill"><span class="dot"></span>PNCP conectado por API</span><span class="avatar small">{{user.name?.charAt(0)}}</span></div></header>
    <main><div v-if="error" role="alert" class="alert error">{{error}}<button @click="error=''" aria-label="Fechar erro"><X :size="16"/></button></div><div v-if="message" role="status" class="alert success">{{message}}<button @click="message=''" aria-label="Fechar mensagem"><X :size="16"/></button></div><div v-if="busy" role="status" class="loading-bar">Processando…</div>
      <template v-if="view==='dashboard'">
        <div class="page-heading"><div><span class="eyebrow">VISÃO GERAL</span><h1>Um radar. Novas possibilidades.</h1><p>Acompanhe as oportunidades certas para os seus próximos projetos.</p></div><button class="primary" @click="synchronize" :disabled="busy"><RefreshCw :size="17"/>Consultar PNCP</button></div>
        <section class="hero"><div><span class="hero-tag"><span class="dot"></span>MONITORAMENTO DE LICITAÇÕES</span><h2>Seu conhecimento técnico.<br>As oportunidades do Brasil.</h2><p>Da busca ao parecer documental, reúna tudo o que precisa<br class="desktop-break"> para decidir quais editais merecem a sua atenção.</p><button @click="go('opportunities')">Explorar oportunidades<ArrowUpRight :size="18"/></button></div><div class="hero-radar" aria-hidden="true"><span></span><span></span><span></span><Radar :size="70"/><i></i><b></b><em></em></div></section>
        <section class="stats"><article><span><Search :size="18"/>Oportunidades abertas</span><strong>{{dashboard.open||0}}</strong><small>Entre os resultados importados</small></article><article><span><Check :size="18"/>Aderentes ao escopo</span><strong>{{dashboard.relevant||0}}</strong><small>Projetos e anteprojetos identificados</small></article><article><span><FileText :size="18"/>Requisitos pendentes</span><strong>{{dashboard.pending||0}}</strong><small>Aguardando análise documental</small></article><article><span><Files :size="18"/>Acervo da empresa</span><strong>{{dashboard.documents||0}}</strong><small>Certificações e atestados cadastrados</small></article></section>
        <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h3>Atividade do radar</h3><p>Histórico das consultas ao PNCP</p></div><button class="text-button" @click="perform(loadDashboard)"><RefreshCw :size="15"/>Atualizar</button></div><div v-if="!dashboard.runs.length" class="empty"><Activity :size="32"/><h3>Vamos encontrar seu próximo projeto?</h3><p>Cadastre a documentação da empresa<br>e inicie a consulta baseada no acervo.</p><button class="secondary" @click="synchronize" :disabled="busy">Iniciar consulta<ArrowUpRight :size="16"/></button></div><div v-for="run in dashboard.runs" :key="run.id" class="activity-row"><span class="activity-icon"><RefreshCw :size="17"/></span><div><strong>Consulta #{{run.id}}</strong><small>{{datetime(run.started_at)}} · {{run.imported}} novas · {{run.matched}} associações</small><small v-if="run.error" class="danger-text">{{run.error}}</small></div><span :class="['badge',run.status]">{{labels[run.status]}}</span></div></section><div class="right-stack"><section class="panel automation"><div class="panel-heading"><h3>Rotina diária</h3><Clock :size="19"/></div><strong class="schedule-time">06:00 <small>horário de Brasília</small></strong><p>O agendamento busca oportunidades com base no acervo da empresa. Perfis ativos refinam os alertas.</p><div class="checkline"><Check :size="16"/>Atualização de oportunidades</div><div class="checkline"><Mail :size="16"/>{{dashboard.mail_configured?'E-mail configurado':'E-mail aguardando configuração SMTP'}}</div><button class="text-button" @click="go('profiles')">Ajustar perfis<ArrowUpRight :size="15"/></button></section><section class="panel"><h3>Seu acervo em dia</h3><p v-if="!dashboard.expiring.length">Cadastre a validade dos documentos para acompanhar vencimentos.</p><div v-for="doc in dashboard.expiring" :key="doc.id" class="expiry"><FileText :size="16"/><span>{{doc.name}}<small>Validade: {{date(doc.expires_at)}}</small></span></div><button class="text-button" @click="go('documents')">Gerenciar documentos<ArrowUpRight :size="15"/></button></section></div></div>
      </template>
      <template v-if="view==='opportunities'">
        <div class="page-heading"><div><span class="eyebrow">BUSCA & SELEÇÃO</span><h1>Oportunidades</h1><p>Editais compatíveis com certidões, atestados, RRT e habilitação do CNPJ da empresa. Os filtros refinam essa seleção.</p></div><button class="primary" @click="synchronize" :disabled="busy"><RefreshCw :size="17"/>Consultar PNCP</button></div>
        <form class="panel filters" @submit.prevent="perform(()=>loadResults())"><div class="filter-grid"><label class="wide">Palavra-chave<input v-model="filters.keyword" placeholder="Ex.: projeto arquitetônico"></label><label>UF<select v-model="filters.state"><option value="">Todo o Brasil</option><option v-for="s in states">{{s}}</option></select></label><label>Modalidade<select v-model="filters.modality"><option value="">Todas</option><option v-for="[id,label] in modalities" :value="id">{{label}}</option></select></label><label>Órgão<input v-model="filters.agency" placeholder="Nome do órgão"></label><label>Valor mínimo<input v-model="filters.min_value" type="number" min="0" step="0.01" placeholder="R$"></label><label>Valor máximo<input v-model="filters.max_value" type="number" min="0" step="0.01" placeholder="R$"></label><label>Prazo até<input v-model="filters.deadline" type="date"></label><label>Aderência<select v-model="filters.scope"><option value="">Todos os resultados</option><option value="relevant">Aderentes ao escopo</option><option value="review">Revisar escopo</option><option value="excluded">Inclui obra</option></select></label></div><div class="filter-footer"><div><span class="meta">Somente editais com prazo aberto</span><label class="checkbox"><input v-model="filters.bookmarked" type="checkbox">Salvas</label><label class="checkbox"><input v-model="filters.discarded" type="checkbox">Descartadas</label></div><button class="primary" :disabled="busy"><Search :size="16"/>Aplicar filtros</button></div></form>
        <p class="panel">{{filters.discarded ? 'Descartadas com prazo aberto. A restauração é permitida até o vencimento; depois, o cadastro será excluído e não será reimportado.' : results.company_notice}}</p><div v-if="!filters.discarded" class="panel export-toolbar"><strong>{{selectedIds.length}} selecionadas para PDF <small>(máximo 50)</small></strong><button class="secondary" @click="selectPage" :disabled="busy || !results.data.length">Selecionar esta página</button><button class="text-button" @click="selectedIds=[]" :disabled="busy || !selectedIds.length">Limpar seleção</button><button class="primary" @click="exportSelected" :disabled="busy || !selectedIds.length">Exportar selecionadas em PDF</button><small>A seleção é mantida ao trocar páginas e filtros. Recarregar a tela limpa a seleção.</small></div><div class="result-heading"><strong>{{results.total}} oportunidades</strong><span>Fonte: Portal Nacional de Contratações Públicas</span></div><div v-if="!results.data.length" class="panel empty"><Search :size="32"/><h3>Nenhum resultado por enquanto</h3><p>Cadastre documentos válidos com texto extraído, consulte o PNCP e confira os filtros. Sem evidência documental, nenhuma oportunidade é recomendada.</p></div>
        <article v-for="item in results.data" :key="item.id" class="opportunity-card"><div class="opportunity-top"><label v-if="!item.discarded" class="checkbox export-choice"><input v-model="selectedIds" type="checkbox" :value="item.id" :disabled="busy || (selectedIds.length>=50 && !selectedIds.includes(item.id))">Selecionar para PDF</label><span :class="['badge',item.scope_status]">{{labels[item.scope_status]}}</span><span class="meta">{{item.modality}}</span><button @click="toggleBookmark(item)" :aria-label="item.bookmarked?'Remover dos salvos':'Salvar oportunidade'" :class="{saved:item.bookmarked}"><Bookmark :size="20" :fill="item.bookmarked?'currentColor':'none'"/></button></div><h3><button @click="openDetail(item.id)">{{item.object}}</button></h3><p>{{item.company_match?.reason}}</p><details><summary>Documentos que sustentam a compatibilidade</summary><div v-for="e in item.company_match?.evidence" :key="e.document_id+'-'+e.page" class="candidate"><button class="text-button" @click="readDocument(e.document_id)">{{e.name}} · página {{e.page}}</button><p>{{e.concepts.join(', ')}}</p><p>{{e.excerpt}}</p></div></details><p class="agency"><Building2 :size="15"/>{{item.agency}}</p><div class="opportunity-bottom"><span><MapPin :size="15"/>{{item.city}} · {{item.state}}</span><span><Clock :size="15"/>{{date(item.deadline)}}</span><strong>{{money(item.estimated_value)}}</strong><button class="text-button" @click="openDetail(item.id)">Analisar edital<ArrowUpRight :size="16"/></button><button class="secondary" @click="toggleDiscard(item)" :disabled="busy">{{item.discarded ? 'Restaurar' : 'Descartar'}}</button></div></article><div v-if="results.last_page>1" class="pagination"><button :disabled="results.current_page===1||busy" @click="perform(()=>loadResults(results.current_page-1))"><ChevronLeft :size="18"/>Anterior</button><span>{{results.current_page}} / {{results.last_page}}</span><button :disabled="results.current_page===results.last_page||busy" @click="perform(()=>loadResults(results.current_page+1))">Próxima<ChevronRight :size="18"/></button></div>
      </template>
      <template v-if="view==='documents'"><div class="page-heading"><div><span class="eyebrow">ACERVO TÉCNICO</span><h1>Documentos da empresa</h1><p>Certidões, atestados, RRT e habilitação do CNPJ que orientam a busca e a análise.</p></div></div><form class="panel upload-form" @submit.prevent="upload()"><label>Arquivo PDF<input type="file" accept="application/pdf" @change="chosenFile=$event.target.files[0]" required><small>Até 20 MB. PDFs digitalizados podem precisar de OCR.</small></label><label>Tipo<select v-model="uploadKind"><option value="attestation">Atestado técnico</option><option value="certificate">Certificação / certidão</option><option value="rrt">Registro de Responsabilidade Técnica - RRT</option><option value="cnpj">CNPJ</option></select></label><label>Validade, se houver<input v-model="expires" type="date"></label><button class="primary" :disabled="busy"><Plus :size="17"/>Adicionar documento</button></form><div v-if="!documents.length" class="panel empty"><Files :size="34"/><h3>Seu acervo começa aqui</h3><p>Adicione os PDFs da empresa para encontrar evidências em cada análise.</p></div><div class="panel document-list" v-else><article v-for="doc in documents" :key="doc.id"><span class="file-icon"><FileText :size="22"/></span><div><strong>{{doc.name}}</strong><small>{{labels[doc.kind]}} · {{doc.pages?.length||0}} páginas · Validade: {{date(doc.expires_at)}}</small><small v-if="doc.error" class="danger-text">{{doc.error}}</small></div><span :class="['badge',doc.status]">{{labels[doc.status]}}</span><button class="text-button" @click="readDocument(doc.id)">Ler texto</button><a :href="'/api/documents/'+doc.id+'/download'" class="text-button">Baixar</a></article></div></template>
      <template v-if="view==='profiles'"><div class="page-heading"><div><span class="eyebrow">MONITORAMENTO</span><h1>Perfis de busca</h1><p>Refine oportunidades compatíveis com o acervo e defina quem receberá as novidades.</p></div><button class="primary" @click="editProfile()"><Plus :size="17"/>Novo perfil</button></div><div class="profile-grid"><article v-for="p in profiles" :key="p.id" class="panel profile-card"><div class="panel-heading"><span class="profile-icon"><SlidersHorizontal :size="22"/></span><span :class="['badge',p.active?'ready':'pending']">{{p.active?'Ativo':'Pausado'}}</span></div><h3>{{p.name}}</h3><p>Base da busca: documentação da empresa</p><p><MapPin :size="15"/>{{p.states?.length?p.states.join(', '):'Todo o Brasil'}}</p><p><Clock :size="15"/>Pelo menos {{p.min_days}} dias para proposta</p><p><Mail :size="15"/>{{p.email||'Alertas apenas no painel'}}</p><div class="profile-actions"><button class="secondary" @click="editProfile(p)">Editar perfil</button><button class="text-button" @click="toggleProfile(p)">{{p.active?'Pausar':'Ativar'}}</button></div></article></div></template>
      <template v-if="view==='detail'&&detail"><button class="text-button back" @click="go('opportunities')"><ChevronLeft :size="16"/>Voltar às oportunidades</button><div class="detail-heading"><span :class="['badge',detail.opportunity.scope_status]">{{labels[detail.opportunity.scope_status]}}</span><h1>{{detail.opportunity.object}}</h1><p>{{detail.opportunity.agency}} · {{detail.opportunity.city}} / {{detail.opportunity.state}}</p><div class="detail-meta"><span>{{money(detail.opportunity.estimated_value)}}</span><span>Prazo: {{date(detail.opportunity.deadline)}}</span><a :href="detail.opportunity.pncp_url" target="_blank" rel="noopener">Abrir no PNCP<ArrowUpRight :size="16"/></a></div></div><section class="panel verdict"><span class="eyebrow">PARECER DOCUMENTAL PRELIMINAR</span><h2>{{detail.verdict}}</h2><p>{{detail.opportunity.scope_reason}}</p><p>{{detail.notice}}</p><h3>Confronto do objeto com o acervo</h3><p>{{detail.opportunity.company_match?.reason}}</p><div v-for="e in detail.opportunity.company_match?.evidence" :key="e.document_id+'-'+e.page" class="candidate"><button class="text-button" @click="readDocument(e.document_id)">{{e.name}} · página {{e.page}}</button><p>{{e.concepts.join(', ')}}</p><p>{{e.excerpt}}</p></div></section><section class="panel"><div class="panel-heading"><h3>Edital e anexos</h3><button class="secondary" @click="fetchAttachments" :disabled="busy">Buscar anexos no PNCP</button></div><p v-if="detail.opportunity.attachments_error" class="error">{{detail.opportunity.attachments_error}}</p><p class="meta">Busca de anexos: {{detail.opportunity.attachments_status}}</p><p>O radar busca PDFs no PNCP automaticamente. Você também pode adicionar anexos manualmente.</p><form class="upload-form" @submit.prevent="upload(true)"><label>PDF do edital<input type="file" accept="application/pdf" required @change="chosenFile=$event.target.files[0]"></label><button class="primary" :disabled="busy">Extrair requisitos</button></form><div v-for="doc in detail.opportunity.documents" :key="doc.id" class="activity-row"><FileText :size="20"/><strong>{{doc.name}}</strong><span :class="['badge',doc.status]">{{labels[doc.status]}}</span><button class="text-button" @click="readDocument(doc.id,true)">Ler páginas</button></div></section><section class="panel requirements"><div class="panel-heading"><div><h3>Requisitos e evidências</h3><p>Trechos extraídos são candidatos e precisam de revisão.</p></div><span>{{detail.opportunity.requirements.length}} itens</span></div><div v-if="!detail.opportunity.requirements.length" class="empty compact"><FileText :size="28"/><p>Adicione um edital e cadastre as exigências que não forem extraídas.</p></div><article v-for="req in detail.opportunity.requirements" :key="req.id" class="requirement"><div class="requirement-top"><span :class="['badge',req.status]">{{labels[req.status]}}</span><button class="text-button" @click="readDocument(req.source_document_id,true)">Edital · página {{req.source_page}}</button></div><h4>{{req.description}}</h4><p v-if="req.notes">Revisão: {{req.notes}}</p><p v-if="req.evidence">Evidência: {{req.evidence.name}} · página {{req.evidence_page}}</p><details v-if="req.candidates.length"><summary>{{req.candidates.length}} evidências candidatas por palavras em comum</summary><div v-for="c in req.candidates" class="candidate"><button class="text-button" @click="readDocument(c.document_id)">{{c.name}} · página {{c.page}}</button><p>{{c.excerpt}}</p></div></details><p v-else class="meta">Nenhuma evidência candidata encontrada.</p><button class="secondary" @click="review(req)">Revisar requisito</button></article><form v-if="detail.opportunity.documents.length" class="manual-requirement" @submit.prevent="addRequirement"><h3>Adicionar exigência não extraída</h3><div class="filter-grid"><label>Documento de origem<select v-model="newReq.source_document_id" required><option value="">Selecione</option><option v-for="d in detail.opportunity.documents" :value="d.id">{{d.name}}</option></select></label><label>Página<input v-model="newReq.source_page" type="number" min="1" required></label><label class="wide">Exigência<textarea v-model="newReq.description" required maxlength="4000"></textarea></label></div><button class="primary" :disabled="busy">Adicionar requisito</button></form></section></template>
      <footer>LicitaRadar <span>Projetos bem escolhidos. Decisões com evidências.</span><span>Fonte de dados: PNCP</span></footer>
    </main></div>
  </div>
  <div v-if="profileForm" class="modal-overlay" @click.self="profileForm=null"><section role="dialog" aria-modal="true" aria-labelledby="profile-title" class="modal"><div class="panel-heading"><h2 id="profile-title">{{profileForm.id?'Editar':'Novo'}} perfil de busca</h2><button @click="profileForm=null" aria-label="Fechar"><X :size="22"/></button></div><form @submit.prevent="saveProfile"><label>Nome do perfil<input v-model="profileForm.name" required maxlength="120"></label><p>A busca usa exclusivamente o acervo da empresa. Este perfil define filtros e alertas.</p><label>UFs, separadas por vírgula<input v-model="profileForm.states" placeholder="Vazio = todo o Brasil"></label><label>Modalidades<select v-model="profileForm.modalities" multiple><option v-for="[id,label] in modalities" :value="id">{{label}}</option></select><small>Nenhuma seleção = todas.</small></label><div class="filter-grid"><label>Órgão<input v-model="profileForm.agency"></label><label>Dias mínimos para proposta<input v-model.number="profileForm.min_days" type="number" min="0" max="365" required></label><label>Valor mínimo<input v-model="profileForm.min_value" type="number" min="0" step="0.01"></label><label>Valor máximo<input v-model="profileForm.max_value" type="number" min="0" step="0.01"></label></div><label>E-mail para alertas<input v-model="profileForm.email" type="email" placeholder="opcional"></label><label class="checkbox"><input v-model="profileForm.active" type="checkbox">Perfil ativo</label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy">Salvar perfil</button></form></section></div>
  <div v-if="reading" class="modal-overlay" @click.self="reading=null"><section class="modal reading" role="dialog" aria-modal="true" aria-label="Texto do PDF"><div class="panel-heading"><h2>{{reading.name}}</h2><button @click="reading=null" aria-label="Fechar"><X :size="22"/></button></div><p v-if="reading.status!=='ready'" class="alert">{{reading.error||'Há páginas sem texto suficiente. Necessário OCR/revisão do PDF original.'}}</p><article v-for="page in reading.pages" :key="page.number"><h3>Página {{page.number}}</h3><pre>{{page.text||'Sem texto extraível.'}}</pre></article></section></div>
  <div v-if="reviewForm" class="modal-overlay" @click.self="reviewForm=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="review-title"><div class="panel-heading"><h2 id="review-title">Revisar requisito</h2><button @click="reviewForm=null" aria-label="Fechar"><X :size="22"/></button></div><p>{{reviewForm.description}}</p><form @submit.prevent="saveReview"><label>Conclusão<select v-model="reviewForm.status"><option value="pending">Pendente</option><option value="met">Atendido</option><option value="unmet">Não atendido</option><option value="not_applicable">Não se aplica</option></select></label><template v-if="reviewForm.status==='met'"><label>Documento que comprova<select v-model="reviewForm.evidence_document_id" required><option value="">Selecione</option><option v-for="d in documents" :value="d.id">{{d.name}}</option></select></label><label>Página da evidência<input v-model="reviewForm.evidence_page" type="number" min="1" required></label></template><label>Fundamentação<textarea v-model="reviewForm.notes" required maxlength="4000" placeholder="Explique sua conclusão e os detalhes relevantes."></textarea></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="busy">Salvar revisão</button></form></section></div>
</template>
